const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
if (data.length === 0) process.exit(0);

const N = data[0];
const adj = Array.from({ length: N + 1 }, () => []);
let ptr = 1;
for (let i = 0; i < N - 1; i++) {
  const x = data[ptr++];
  const y = data[ptr++];
  adj[x].push(y);
  adj[y].push(x);
}

function bfs(start) {
  const dist = new Int32Array(N + 1).fill(-1);
  const parent = new Int32Array(N + 1);
  const queue = new Int32Array(N);
  let head = 0, tail = 0;

  queue[tail++] = start;
  dist[start] = 0;
  let far = start;

  while (head < tail) {
    const u = queue[head++];
    const du = dist[u];
    const neighbors = adj[u];

    for (let i = 0; i < neighbors.length; i++) {
      const v = neighbors[i];
      if (dist[v] === -1) {
        dist[v] = du + 1;
        parent[v] = u;
        queue[tail++] = v;
        if (dist[v] > dist[far]) far = v;
      }
    }
  }

  return { far, dist, parent };
}

function countAtDepth(start, blocked, target) {
  if (target === 0) return 1;

  let count = 0;
  const stack = [[start, blocked, 0]];

  while (stack.length > 0) {
    const item = stack.pop();
    const u = item[0];
    const p = item[1];
    const d = item[2];

    if (d === target) {
      count++;
      continue;
    }

    const nd = d + 1;
    const neighbors = adj[u];

    for (let i = 0; i < neighbors.length; i++) {
      const v = neighbors[i];
      if (v !== p) {
        stack.push([v, u, nd]);
      }
    }
  }

  return count;
}

const first = bfs(1);
const A = first.far;

const second = bfs(A);
const B = second.far;
const D = second.dist[B];
const parent = second.parent;

const path = [];
let cur = B;
while (true) {
  path.push(cur);
  if (cur === A) break;
  cur = parent[cur];
}
path.reverse();

const maxCycleLength = D + 1;
let ways;

if (D % 2 === 0) {
  const c = path[D / 2];
  const r = D / 2;

  let total = 0;
  let sumSq = 0;

  const neighbors = adj[c];
  for (let i = 0; i < neighbors.length; i++) {
    const cnt = countAtDepth(neighbors[i], c, r - 1);
    total += cnt;
    sumSq += cnt * cnt;
  }

  ways = (total * total - sumSq) / 2;
} else {
  const c1 = path[Math.floor(D / 2)];
  const c2 = path[Math.floor(D / 2) + 1];
  const r = Math.floor(D / 2);

  const cnt1 = countAtDepth(c1, c2, r);
  const cnt2 = countAtDepth(c2, c1, r);

  ways = cnt1 * cnt2;
}

process.stdout.write(maxCycleLength + '\n' + ways + '\n');
